using System;using System.ComponentModel;using System.Windows;using System.Windows.Media;using System.Windows.Media.Animation;using KonveyorWpf.ViewModels;namespace KonveyorWpf{    public partial class MainWindow : Window    {        private MainViewModel? _viewModel;        public MainWindow()        {            InitializeComponent();            Loaded += (s, e) => RegisterViewModel();            DataContextChanged += (s, e) => RegisterViewModel();        }        private void RegisterViewModel()        {            if (_viewModel != null)            {                _viewModel.PropertyChanged -= ViewModel_PropertyChanged;            }            if (DataContext is MainViewModel vm)            {                _viewModel = vm;                _viewModel.PropertyChanged += ViewModel_PropertyChanged;            }        }        private void ViewModel_PropertyChanged(object? sender, PropertyChangedEventArgs e)        {            if (e.PropertyName == nameof(MainViewModel.IsPistonActive))            {                if (_viewModel != null)                {                    AnimatePistonRod(_viewModel.IsPistonActive);                }            }        }        private void AnimatePistonRod(bool isExtending)        {            // Smoothly animate Piston Rod Y translation (0 -> 45 pixels downwards)            double targetY = isExtending ? 45.0 : 0.0;            DoubleAnimation anim = new DoubleAnimation            {                To = targetY,                Duration = TimeSpan.FromMilliseconds(250),                EasingFunction = new QuadraticEase { EasingMode = isExtending ? EasingMode.EaseOut : EasingMode.EaseIn }            };            PistonTransform.BeginAnimation(TranslateTransform.YProperty, anim);        }    }}